const bin = $input.item.binary || {};
const keys = Object.keys(bin);
if (!keys.length) throw new Error('Nenhum arquivo recebido.');
const parts = [];
for (const k of keys) {
  const buf = await this.helpers.getBinaryDataBuffer($itemIndex, k);
  parts.push({ inline_data: { mime_type: bin[k].mimeType || 'application/pdf', data: buf.toString('base64') } });
}
const prompt = [
  'Você é um assistente contábil. O arquivo acima é o PDF de UMA fatura de cartão de crédito.',
  'Liste TODOS os lançamentos DESTA fatura, na ordem em que aparecem, de TODOS os cartões (titular e adicionais). Devolva SOMENTE JSON válido (sem markdown).',
  'Regras:',
  '- IGNORE o pagamento da fatura anterior ("Pagamento Recebido", "Pagamento efetuado", "Obrigado pelo pagamento") e o saldo/total da fatura anterior: coloque em pagamentos_ignorados.',
  '- NÃO inclua linhas de subtotal/total. Não pule nem junte linhas. Estornos e créditos entram com valor NEGATIVO.',
  '- data: a data impressa na linha (DD/MM) = data da compra. parcela: "N/T" se aparecer "Parcela N de T", "NN/TT" ou "N DE T" junto da descrição, senão "". ATENÇÃO: "03/12" no fim da descrição é PARCELA, não data.',
  '- descricao: texto do estabelecimento exatamente como aparece. valor: número com ponto decimal, em R$ (compra internacional: use o valor em R$).',
  '- vencimento: data de vencimento desta fatura (AAAA-MM-DD). total_impresso: o TOTAL A PAGAR desta fatura.',
  '- CONFERÊNCIA: a soma dos valores deve bater com total_impresso; se não bater, releia antes de responder.',
  '- Se não tiver certeza de alguma linha, inclua e explique em duvidas.',
  'Formato: {"vencimento":"AAAA-MM-DD","total_impresso":0,"lancamentos":[{"data":"DD/MM","descricao":"","valor":0,"parcela":""}],"pagamentos_ignorados":[{"descricao":"","valor":0}],"duvidas":[]}'
].join('\n');
parts.push({ text: prompt });
return { json: { arquivos: keys.length, body: { contents: [{ parts }], generationConfig: { responseMimeType: 'application/json', temperature: 0 } } } };

const fm = $('Enviar fatura do cartão').first().json;
const cliente = fm.cliente || 'Cliente';
const raw = ($input.first().json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
if (!raw.trim()) throw new Error('A IA não devolveu nada.');
let f; try { f = JSON.parse(raw); } catch (e) { f = JSON.parse(raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); }
const venc = /^\d{4}-\d{2}-\d{2}/.test(String(f.vencimento || '')) ? String(f.vencimento).slice(0, 10) : '';
const vy = venc ? Number(venc.slice(0, 4)) : new Date().getFullYear();
const toISO = t => { const m = String(t || '').match(/(\d{1,2})\s*\/\s*(\d{1,2})(?:\s*\/\s*(\d{2,4}))?/); if (!m) return ''; const d = m[1].padStart(2, '0'), mo = m[2].padStart(2, '0');
  if (m[3]) return (m[3].length === 2 ? '20' + m[3] : m[3]) + '-' + mo + '-' + d; let iso = vy + '-' + mo + '-' + d; if (venc && iso > venc) iso = (vy - 1) + '-' + mo + '-' + d; return iso; };
const br = iso => iso ? iso.split('-').reverse().join('/') : '';
const r2 = v => Math.round(Number(v) * 100) / 100, cents = v => Math.round(Number(v) * 100);
const brl = v => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
// Sugestão de categoria por palavra (a Redacted confere). Ajustar com o padrão de cada cliente.
const REGRAS = [
  [/ANUIDADE|TARIFA|IOF|JUROS|ENCARGO/, 'Tarifas bancárias / cartão'],
  [/IFD|IFOOD|RESTAUR|LANCH|PADARIA|CAFE|BOLO/, 'Alimentação'],
  [/UBER|99 ?APP|POSTO|COMBUST|ESTACION/, 'Transporte / combustível'],
  [/OLX|ANUNCI|FACEBK|FACEBOOK|GOOGLE ADS|INSTAGRAM/, 'Marketing / anúncios'],
  [/GOOGLE|MICROSOFT|ADOBE|CANVA|APPLE|OPENAI|ZOOM/, 'Sistemas e aplicativos'],
  [/MERCADOLIVRE|MERCADO LIVRE|MAGALU|AMAZON|SHOPEE|PRODUTOS|SONHOEARTE/, 'Compras / materiais (a classificar)'],
  [/COLCHO|MOVEIS|MOVEL/, 'Móveis e utensílios (a classificar)'],
  [/ASSISTENCIA|LETZTECH|INFORMAT|TECH/, 'Manutenção / tecnologia (a classificar)']
];
const PREF = /^(MP|ZP|EC|PG|PAG|IFD|DL|EBN|WWW|JIM)\s*\*?\s*/i;
const linhas = (f.lancamentos || []).filter(l => cents(l.valor) !== 0).map((l, i) => {
  const descricao = String(l.descricao || '').trim();
  const p = String(l.parcela || '').match(/(\d{1,2})\s*\/\s*(\d{1,2})/);
  const r = REGRAS.find(([re]) => re.test(norm(descricao)));
  const fornecedor = descricao.replace(PREF, '').replace(/\*/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
  return { n: i + 1, dataCompra: toISO(l.data), descricao, parcela: p ? p[1] + '/' + p[2] : '', valor: r2(l.valor), credito: Number(l.valor) < 0,
    fornecedor, categoria: r ? r[1] : 'A classificar', descricaoCA: (p ? p[1] + '/' + p[2] + ' - ' : '') + descricao.toUpperCase() };
});
const soma = r2(linhas.reduce((s, l) => s + l.valor, 0));
const total = f.total_impresso !== null && f.total_impresso !== undefined && f.total_impresso !== '' ? r2(f.total_impresso) : null;
const bate = total === null ? null : cents(total) === cents(soma);
const cab = ['Data da compra (competência)', 'Vencimento', 'Descrição', 'Parcela', 'Fornecedor (sugestão)', 'Categoria (sugestão)', 'Tipo', 'Valor'];
const csvLinhas = linhas.map(l => [br(l.dataCompra), br(venc), l.descricaoCA, l.parcela, l.fornecedor, l.categoria, l.credito ? 'Receita/estorno' : 'Despesa', String(Math.abs(l.valor).toFixed(2)).replace('.', ',')]);
const csv = '﻿' + [cab].concat(csvLinhas).map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(';')).join('\r\n');
const csvB64 = Buffer.from(csv, 'utf8').toString('base64');
const td = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;vertical-align:top"', tdr = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;text-align:right;white-space:nowrap"', th = 'style="padding:4px 6px;border-bottom:2px solid #333;font-size:12px;text-align:left"';
const card = (t, v, cor) => '<div style="display:inline-block;margin:4px;padding:8px 12px;border:1px solid #ccc;border-radius:6px;min-width:120px"><div style="font-size:11px;color:#555">' + t + '</div><div style="font-size:18px;font-weight:bold;color:' + (cor || '#222') + '">' + v + '</div></div>';
let h = '<div style="font-family:Arial,sans-serif;text-align:left;max-width:1100px;margin:auto"><h2 style="margin:4px 0">' + esc(cliente) + ' — fatura do cartão venc. ' + (br(venc) || '(não encontrado no PDF)') + '</h2>';
h += '<p style="font-size:13px">' + (bate === true ? '<b style="color:#1b7f3b">✅ A soma das linhas bate com o total da fatura (' + brl(total) + ').</b>' : bate === false ? '<b style="color:#c0392b">⚠️ A soma (' + brl(soma) + ') NÃO bate com o total da fatura (' + brl(total) + '). Diferença ' + brl(soma - total) + ' — confira se alguma linha foi lida errado.</b>' : '<b style="color:#b26a00">Não achei o total no PDF: confira a soma abaixo.</b>') + '</p>';
h += '<div>' + card('Lançamentos', linhas.length) + card('Soma', brl(soma), bate === false ? '#c0392b' : bate ? '#1b7f3b' : '#222') + card('Total da fatura', total === null ? '?' : brl(total)) + card('Pagamentos ignorados', (f.pagamentos_ignorados || []).length, '#666') + '</div>';
if ((f.duvidas || []).filter(Boolean).length) h += '<p style="color:#b26a00;font-size:12px"><b>Dúvidas da leitura:</b> ' + f.duvidas.filter(Boolean).map(esc).join(' | ') + '</p>';
h += '<p><a download="' + esc(cliente) + ' fatura ' + br(venc).replace(/\//g, '-') + '.csv" href="data:text/csv;base64,' + csvB64 + '" style="display:inline-block;padding:10px 16px;background:#1b7f3b;color:#fff;border-radius:6px;text-decoration:none;font-weight:bold">⬇ Baixar planilha (Excel)</a></p>';
h += '<table style="border-collapse:collapse;width:100%"><tr><th ' + th + '>#</th><th ' + th + '>Data compra</th><th ' + th + '>Descrição para o Conta Azul</th><th ' + th + '>Fornecedor (sugestão)</th><th ' + th + '>Categoria (sugestão)</th><th ' + th + '>Valor</th></tr>';
linhas.forEach(l => { h += '<tr><td ' + td + '>' + l.n + '</td><td ' + td + '>' + br(l.dataCompra) + '</td><td ' + td + '>' + esc(l.descricaoCA) + '</td><td ' + td + '>' + esc(l.fornecedor) + '</td><td ' + td + '>' + esc(l.categoria) + '</td><td ' + tdr + '>' + (l.credito ? '<span style="color:#1b7f3b">estorno ' + brl(Math.abs(l.valor)) + '</span>' : brl(l.valor)) + '</td></tr>'; });
h += '</table>';
if ((f.pagamentos_ignorados || []).length) h += '<p style="font-size:12px;color:#666">Pagamentos de fatura ignorados: ' + f.pagamentos_ignorados.map(p => esc(p.descricao) + ' ' + brl(p.valor)).join(' | ') + '</p>';
h += '<p style="font-size:11px;color:#888">Nada foi lançado: confira e lance no Conta Azul.</p></div>';
return [{ json: { cliente, vencimento: venc, soma, total, bate, linhas, pagamentos: f.pagamentos_ignorados || [], duvidas: f.duvidas || [], html: h } }];
